function loadWorkspace() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORE_KEY));
    if(!saved)return seed;
    const merged={...seed,...saved};
    // Add newly shipped starter controls without overwriting anything the user has edited.
    merged.frameworks=[...(Array.isArray(saved.frameworks)?saved.frameworks:[]),...seed.frameworks.filter(row=>!(saved.frameworks||[]).some(existing=>existing.id===row.id))];
    return merged;
  } catch { return seed; }
}

