function Icon({name,size=16}) {
  const p={grid:<><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/></>,users:<><path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/></>,userplus:<><path d="M15 21v-2a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M19 8v6m-3-3h6"/></>,userminus:<><path d="M15 21v-2a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M16 11h6"/></>,key:<><circle cx="8" cy="15" r="5"/><path d="m21 2-9.6 9.6M15.5 7.5l3 3L22 7l-3-3"/></>,license:<><path d="M4 4.5A2.5 2.5 0 0 1 6.5 2H20v18H6.5A2.5 2.5 0 0 1 4 17.5z"/><path d="M4 17.5A2.5 2.5 0 0 1 6.5 15H20M8 6h8M8 10h5"/></>,audit:<><path d="M8 4h11v17H5V7z"/><path d="M8 3v4H4M9 12h6m-6 4h6"/><circle cx="17" cy="17" r="4"/><path d="m20 20 2 2"/></>,risk:<><path d="m12 3 9 17H3z"/><path d="M12 9v5m0 3h.01"/></>,shield:<><path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11"/><path d="m9 12 2 2 4-4"/></>,search:<><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></>,bell:<><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></>,plus:<path d="M12 5v14m-7-7h14"/>,arrow:<path d="M5 12h14m-7-7 7 7-7 7"/>,clock:<><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></>,check:<path d="m5 12 4 4L19 6"/>,download:<><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="m7 10 5 5 5-5m-5 5V3"/></>,close:<path d="m18 6-12 12M6 6l12 12"/>,help:<><circle cx="12" cy="12" r="9"/><path d="M9.6 9a2.5 2.5 0 1 1 4.5 1.5c-1.2 1.1-2.1 1.6-2.1 3"/><path d="M12 17h.01"/></>};
  return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{p[name]||p.grid}</svg>;
}

function useWorkspace() {
  const [data,setData]=useState(loadWorkspace);
  useEffect(()=>{ localStorage.setItem(STORE_KEY,JSON.stringify(data)); },[data]);
  const update=(key,fn)=>setData(prev=>({...prev,[key]:typeof fn==='function'?fn(prev[key]):fn}));
  const addActivity=(message)=>setData(prev=>({...prev,activity:[{id:crypto.randomUUID(),message,at:new Date().toISOString()},...prev.activity].slice(0,100)}));
  return {data,setData,update,addActivity};
}

function downloadCSV(filename,rows) {
  if(!rows?.length){window.alert('There are no records to export.');return;}
  const columns=[...new Set(rows.flatMap(row=>Object.keys(row)))];
  const quote=value=>{let text=String(value??'');if(/^[=+@\-\t\r]/.test(text))text=`'${text}`;return `"${text.replaceAll('"','""')}"`;};
  const csv=[columns.map(quote).join(','),...rows.map(row=>columns.map(col=>quote(row[col])).join(','))].join('\r\n');
  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
  const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

