        {active==='Staff Offboarding'&&<OffboardingView data={data} search={search} onToggle={(id,key)=>{const person=data.offboarding.find(x=>x.id===id);const turningOn=person&&!person[key];act(key==='assetsReturned'?'Asset return recorded':'Access revocation recorded',()=>{update('offboarding',r=>r.map(x=>{if(x.id!==id)return x;const next={...x,[key]:!x[key]};next.status=next.accessRevoked&&next.assetsReturned?'Completed':next.accessRevoked?'Asset return':'Access revocation';return next;}));if(turningOn&&key==='assetsReturned'&&person)update('assets',r=>r.map(x=>x.assigned===person.name?{...x,assigned:'Unassigned',status:'Available',reviewed:today()}:x));if(turningOn&&key==='accessRevoked'&&person){update('access',r=>r.map(x=>x.user===person.name?{...x,status:'Revoked'}:x));update('accessRequests',r=>r.map(x=>x.name===person.name&&x.status==='Pending'?{...x,status:'Denied'}:x));}});}}/>}
